// プールを使い切ったら 0(NULL)を返すことを確かめる
#include "lib.h"

int heap_init(char *buf, int size);
char *my_malloc(int size);

int main() {
    char *pool;
    char *p;
    int count;

    pool = malloc(512);
    heap_init(pool, 512);
    count = 0;
    p = my_malloc(64);
    while (p != 0) {
        count = count + 1;
        if (count > 100) {
            return 99;      // 無限に確保できてしまっている
        }
        p = my_malloc(64);
    }
    return count;           // 確保できた個数(ヘッダのぶん 512/80 = 6 個)
}

// 自前 malloc で連結リストを作って走査する(コマ12 の再現)
#include "lib.h"

int heap_init(char *buf, int size);
char *my_malloc(int size);

struct Node {
    int val;
    struct Node *next;
};

int main() {
    char *pool;
    struct Node *head;
    struct Node *n;
    int sum;
    int i;

    pool = malloc(1024);
    heap_init(pool, 1024);
    head = 0;
    for (i = 1; i <= 3; i = i + 1) {
        n = my_malloc(sizeof(struct Node));
        n->val = i * 10;
        n->next = head;
        head = n;
    }
    sum = 0;
    while (head != 0) {
        sum = sum + head->val;
        head = head->next;
    }
    return sum;
}

// 解放したブロックが再利用されることを確かめる
#include "lib.h"

int heap_init(char *buf, int size);
char *my_malloc(int size);
int my_free(char *p);
int heap_used();

int main() {
    char *pool;
    char *a;
    char *b;
    char *c;

    pool = malloc(1024);
    heap_init(pool, 1024);
    a = my_malloc(16);
    b = my_malloc(16);
    my_free(b);
    c = my_malloc(16);      // b の跡地が再利用されるはず

    if (b != c) {
        return 1;           // 再利用されなかった
    }
    if (heap_used() != 32) {
        return 2;           // 使用量が合わない(16 x 2)
    }
    return 0;
}

