// 右辺が評価されなかったことを、副作用の有無で確かめる
int counter;

int bump() {
    counter = counter + 1;
    return 1;
}

int main() {
    counter = 0;
    if (0 && bump()) { return 90; }      // bump は呼ばれないはず
    if (counter != 0) { return 91; }

    if (1 || bump()) { }                 // bump は呼ばれないはず
    if (counter != 0) { return 92; }

    if (1 && bump()) { }                 // ここでは呼ばれる
    if (counter != 1) { return 93; }

    return counter;                      // 1
}

// && と || が返す値そのものを確かめる(1 か 0)
int main() {
    int a;
    a = 0;
    if ((1 && 1) != 1) { return 1; }
    if ((1 && 0) != 0) { return 2; }
    if ((0 && 1) != 0) { return 3; }
    if ((5 && 3) != 1) { return 4; }     // 非0同士は 1
    if ((0 || 0) != 0) { return 5; }
    if ((0 || 7) != 1) { return 6; }     // 非0は 1 に正規化
    if ((2 || 3) != 1) { return 7; }
    a = 1 && 1 && 0;
    if (a != 0) { return 8; }
    a = 0 || 0 || 4;
    if (a != 1) { return 9; }
    return 42;
}

// 掛け算も32bitで折り返す
int main() {
    int x;
    int y;

    x = 100000;
    y = x * x;           // 10^10 は int に収まらない → 折り返す
    if (y != 1410065408) { return 1; }    // 32bit で折り返した値と一致するはず

    x = 65536;
    if (x * x != 0) { return 2; }         // 2^32 は 32bit では 0

    return 7;
}

// int は32bitなので、最大値に1を足すと最小値に折り返す
int main() {
    int x;
    x = 2147483647;      // int の最大値
    x = x + 1;
    if (x > 0) { return 1; }        // 折り返していなければ正のまま
    if (x != (-2147483647 - 1)) { return 2; }

    x = (-2147483647 - 1);     // int の最小値
    x = x - 1;
    if (x < 0) { return 3; }        // 折り返して正になるはず
    if (x != 2147483647) { return 4; }

    return 42;
}

