// 構造体の代入(まるごとコピー)
struct Point { int x; int y; };

int main() {
    struct Point p;
    struct Point q;
    p.x = 3;
    p.y = 4;

    q = p;                 // まるごとコピー
    if (q.x != 3) { return 1; }
    if (q.y != 4) { return 2; }

    p.x = 99;              // コピーなので q は影響を受けない
    if (q.x != 3) { return 3; }

    return q.x + q.y;
}

// ポインタ・フィールドを持つ構造体の代入
struct Point { int x; int y; };
struct Line { struct Point *a; struct Point *b; };

int main() {
    struct Point p;
    struct Point q;
    struct Line l;
    struct Line m;

    p.x = 1; p.y = 2;
    q.x = 10; q.y = 20;

    l.a = &p;
    l.b = &q;

    if (l.a->x != 1) { return 1; }
    if (l.b->y != 20) { return 2; }

    m = l;                 // ポインタ2本(16バイト)をまるごとコピー
    if (m.a->x != 1) { return 3; }
    if (m.b->y != 20) { return 4; }

    // ポインタのコピーなので m.a と l.a は同じ Point を指す
    p.x = 99;
    if (m.a->x != 99) { return 5; }

    return m.a->x + m.a->y + m.b->x + m.b->y;
}

// ポインタ経由の構造体代入
struct Box { int w; int h; int d; };

int fill(struct Box *dst, struct Box *src) {
    *dst = *src;           // ポインタの先どうしをコピー
    return 0;
}

int main() {
    struct Box a;
    struct Box b;
    a.w = 2; a.h = 3; a.d = 5;

    fill(&b, &a);
    if (b.w != 2) { return 1; }
    if (b.h != 3) { return 2; }
    if (b.d != 5) { return 3; }

    return b.w * b.h * b.d;
}
